"""Generate ``docs/endpoints.md`` from the endpoint registry.

Usage::

    uv run scripts/gen_docs.py          # regenerate
    uv run scripts/gen_docs.py --check  # exit 1 if out of date
"""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

from pse_sdk._endpoint_spec import EndpointSpec
from pse_sdk._registry import REGISTRY

OUTPUT = Path(__file__).resolve().parents[1] / "docs" / "endpoints.md"

HEADER = """\
<!-- Generated by scripts/gen_docs.py. Do not edit by hand. -->
# Endpoints

> API reference: `https://api.raporty.pse.pl/api/openapi`

Data columns of every endpoint, in API order. Meta columns (`dtime`, `period`,
`business_date`, `publication_ts` and their `*_utc` variants) are left out;
`fetch()` returns them with every request.

| Endpoint | Column | Type |
|---|---|---|
"""


def natural_key(name: str) -> list[str | int]:
    """Sort key that orders digit runs numerically (``kpi2`` before ``kpi10``)."""
    return [int(part) if part.isdigit() else part for part in re.split(r"(\d+)", name)]


def render(registry: dict[str, EndpointSpec]) -> str:
    """Render the endpoints table for *registry*."""
    rows = []
    for name in sorted(registry, key=natural_key):
        spec = registry[name]
        for column, type_ in spec.columns.items():
            if column not in spec.meta_columns:
                rows.append(f"| `{name}` | `{column}` | {type_} |\n")
    return HEADER + "".join(rows)


def _check(source: str) -> int:
    """Return 1 if the committed docs differ from *source*, else 0."""
    current = OUTPUT.read_text(encoding="utf-8") if OUTPUT.exists() else None
    if current != source:
        print(
            f"{OUTPUT.name} is out of date. Run: uv run scripts/gen_docs.py",
            file=sys.stderr,
        )
        return 1
    print(f"{OUTPUT.name} is up to date.")
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="exit 1 if the committed docs are out of date",
    )
    args = parser.parse_args(argv)

    source = render(REGISTRY)

    if args.check:
        return _check(source)

    OUTPUT.write_text(source, encoding="utf-8", newline="\n")
    print(f"Wrote {len(REGISTRY)} endpoints to {OUTPUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
